package io.github.jesterportfolio.hearth.economy;
import java.util.*;import java.util.concurrent.*;import java.util.function.*;import java.security.*;
import io.github.jesterportfolio.hearth.persistence.*;import io.github.jesterportfolio.hearth.inventory.*;
/** 요청 ID·난수·결과·원본 지문·화폐·native shadow를 한 PG commit에 고정한다. */
public final class EnchantStore {
    public record Intent(UUID request,String fingerprint,String action,String enchant,InventoryPayload before,InventoryPayload after,String outcome,double chance,double roll,long cost,long revision){public Intent{Objects.requireNonNull(request);Objects.requireNonNull(fingerprint);Objects.requireNonNull(before);Objects.requireNonNull(after);if(!Set.of("APPLY","FUSE","EXTRACT","IDENTIFY","GRANT").contains(action)||!enchant.matches("hearth:[a-z][a-z0-9_]{0,48}")||fingerprint.length()>2048||!Double.isFinite(chance)||chance<0||chance>1||!Double.isFinite(roll)||roll<0||roll>=1||cost<0||revision<0)throw new IllegalArgumentException("ENCHANT_INTENT");}}
    public record Receipt(UUID request,String outcome,double chance,double roll,long cost,long revision,InventoryPayload after,String afterHash,boolean replay){}
    private final PostgresProgressStore db;private final EconomyStore economy;
    public EnchantStore(PostgresProgressStore db,EconomyStore economy){this.db=db;this.economy=economy;}
    public CompletionStage<Receipt> execute(ServerProgressAccess.Context ctx,Intent i,BooleanSupplier current){return db.module("enchant_operation",c->{c.setAutoCommit(false);try{economy.housingLock(c,ctx);try(var s=c.prepareStatement("SELECT player_uuid,fingerprint,outcome,chance,roll,cost,revision,after_hash FROM hearth_economy.enchant_operation WHERE realm_id=? AND request_id=?")){s.setObject(1,ctx.storyRunId());s.setObject(2,i.request());try(var r=s.executeQuery()){if(r.next()){if(!ctx.playerId().equals(r.getObject(1,UUID.class))||!i.fingerprint().equals(r.getString(2)))throw fail("ENCHANT_REQUEST_CONFLICT");var result=new Receipt(i.request(),r.getString(3),r.getDouble(4),r.getDouble(5),r.getLong(6),r.getLong(7),null,r.getString(8),true);c.commit();return result;}}}if(!current.getAsBoolean())throw fail("ECON_REQUEST_BUSY");
        try(var s=c.prepareStatement("UPDATE hearth_economy.account SET balance=balance-?,payload=?,inventory_revision=inventory_revision+1 WHERE realm_id=? AND player_uuid=? AND inventory_revision=? AND balance>=?")){s.setLong(1,i.cost());s.setBytes(2,i.after().bytes());s.setObject(3,ctx.storyRunId());s.setObject(4,ctx.playerId());s.setLong(5,i.revision());s.setLong(6,i.cost());if(s.executeUpdate()!=1)throw fail("ECON_QUOTE_CHANGED");}
        try(var s=c.prepareStatement("INSERT INTO hearth_economy.enchant_operation(realm_id,request_id,player_uuid,fingerprint,action,enchant_id,before_hash,after_hash,outcome,chance,roll,cost,revision) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)")){int n=0;s.setObject(++n,ctx.storyRunId());s.setObject(++n,i.request());s.setObject(++n,ctx.playerId());s.setString(++n,i.fingerprint());s.setString(++n,i.action());s.setString(++n,i.enchant());s.setString(++n,HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(i.before().bytes())));s.setString(++n,hash(i.after()));s.setString(++n,i.outcome());s.setDouble(++n,i.chance());s.setDouble(++n,i.roll());s.setLong(++n,i.cost());s.setLong(++n,i.revision()+1);s.executeUpdate();}if(!current.getAsBoolean())throw fail("ECON_REQUEST_BUSY");c.commit();return new Receipt(i.request(),i.outcome(),i.chance(),i.roll(),i.cost(),i.revision()+1,i.after(),hash(i.after()),false);
    }catch(Exception e){c.rollback();throw e;}finally{c.setAutoCommit(true);}});}
    public CompletionStage<Optional<String>> inspect(ServerProgressAccess.Context ctx,UUID id){return db.module("enchant_inspect",c->{economy.housingLock(c,ctx);try(var s=c.prepareStatement("SELECT action,enchant_id,outcome,chance,roll,cost,revision,before_hash,after_hash,fingerprint FROM hearth_economy.enchant_operation WHERE realm_id=? AND request_id=? AND player_uuid=?")){s.setObject(1,ctx.storyRunId());s.setObject(2,id);s.setObject(3,ctx.playerId());try(var r=s.executeQuery()){if(!r.next())return Optional.empty();return Optional.of("action="+r.getString(1)+" enchant="+r.getString(2)+" outcome="+r.getString(3)+" chance="+r.getDouble(4)+" roll="+r.getDouble(5)+" cost="+r.getLong(6)+" revision="+r.getLong(7)+" before="+r.getString(8)+" after="+r.getString(9)+" fingerprint="+r.getString(10));}}});}
    public CompletionStage<List<String>> history(ServerProgressAccess.Context ctx){return db.module("enchant_history",c->{economy.housingLock(c,ctx);try(var s=c.prepareStatement("SELECT request_id,action,enchant_id,outcome,cost FROM hearth_economy.enchant_operation WHERE realm_id=? AND player_uuid=? ORDER BY created_at DESC,request_id LIMIT 20")){s.setObject(1,ctx.storyRunId());s.setObject(2,ctx.playerId());var out=new ArrayList<String>();try(var r=s.executeQuery()){while(r.next())out.add(r.getObject(1)+" "+r.getString(2)+" "+r.getString(3)+" "+r.getString(4)+" "+r.getLong(5));}return List.copyOf(out);}});}
    public CompletionStage<Map<UUID,Map<String,Long>>> cooldowns(UUID realm,long now){return db.module("enchant_cooldowns_load",c->{economy.housingLock(c,economy.context(realm,new UUID(0,0)));var out=new HashMap<UUID,Map<String,Long>>();try(var s=c.prepareStatement("SELECT player_uuid,enchant_id,until_millis FROM hearth_economy.enchant_cooldown WHERE realm_id=? AND until_millis>?")){s.setObject(1,realm);s.setLong(2,now);try(var r=s.executeQuery()){int count=0;while(r.next()){if(++count>16384)throw fail("ENCHANT_COOLDOWN_CAPACITY");out.computeIfAbsent(r.getObject(1,UUID.class),x->new HashMap<>()).put(r.getString(2),r.getLong(3));}}}out.replaceAll((key,value)->Map.copyOf(value));return Map.copyOf(out);});}
    public CompletionStage<Void> saveCooldowns(UUID realm,Map<UUID,Map<String,Long>> values){return db.module("enchant_cooldowns_save",c->{c.setAutoCommit(false);try{economy.housingLock(c,economy.context(realm,new UUID(0,0)));try(var s=c.prepareStatement("INSERT INTO hearth_economy.enchant_cooldown VALUES(?,?,?,?) ON CONFLICT(realm_id,player_uuid,enchant_id) DO UPDATE SET until_millis=GREATEST(hearth_economy.enchant_cooldown.until_millis,EXCLUDED.until_millis)")){int count=0;for(var player:values.entrySet())for(var row:player.getValue().entrySet()){if(++count>16384||!row.getKey().matches("hearth:[a-z][a-z0-9_]{0,48}")||row.getValue()<=0)throw fail("ENCHANT_COOLDOWN");s.setObject(1,realm);s.setObject(2,player.getKey());s.setString(3,row.getKey());s.setLong(4,row.getValue());s.addBatch();}s.executeBatch();}c.commit();return null;}catch(Exception e){c.rollback();throw e;}finally{c.setAutoCommit(true);}});}
    public static String hash(InventoryPayload payload){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(payload.bytes()));}catch(Exception e){throw new IllegalStateException(e);}}
    private static StorageFailure fail(String code){return new StorageFailure("enchants",code);}
}
